INSERT INTO `maintenance` (`etat_app`, `etat_plomberie`, `etat_electricite`, `etat_chauffage`, `date_derniere_maintenance`, `description_maint`, `id_app`, `id_maintenance`, `recommendation_ia`) VALUES
('bon', 'moyen', 'moyen', 'bon', '2026-05-08', NULL, 1, 3, 'Etat: Modéré\nActions:\nVérifier et entretenir les canalisations d\'eau pour éviter les fuites potentielles.\nFaire inspecter le tableau électrique et remplacer les composants défectueux si nécessaire.\nContrôler l\'état des radiateurs et du système de chauffage pour maintenir l\'efficacité énergétique.\n\nDate de maintenance Recommendée: 2026-06-05'),
('bon', 'bon', 'mauvais', 'mauvais', '2022-10-31', NULL, 2, 4, 'Etat: Critique\r\nActions: Vérifier et réparer les installations électriques défectueuses.\r\nInspecter et remplacer les éléments du système de chauffage défaillants.\r\nEffectuer une mise à jour complète de la maintenance préventive.\r\nDate de maintenance Recommendée: 2026-03-20'),
('mauvais', 'bon', 'bon', 'mauvais', '2021-04-16', NULL, 3, 5, 'Etat: Critique\r\nActions: Remplacer le système de chauffage défectueux.\r\nNettoyer et inspecter les conduits de ventilation.\r\nVérifier l\'isolation thermique des fenêtres et portes.\r\nDate de maintenance Recommendée: 2026-03-20'),
('mauvais', 'bon', 'bon', 'bon', '2022-06-17', NULL, 4, 6, 'Etat: Critique\nActions: Réparer les éléments structurels endommagés (fissures, peinture écaillée, etc.).\nInspecter et renforcer les parties communes (escaliers, balcons) si nécessaire.\nVérifier l\'isolation thermique et acoustique pour améliorer le confort.\nDate de maintenance Recommendée: 2026-03-23'),
('mauvais', 'bon', 'bon', 'bon', '2024-10-25', NULL, 5, 7, 'Etat: Critique\r\nActions: Réparer les murs et sols endommagés, vérifier l\'isolation et les menuiseries, nettoyer les parties communes.\r\nDate de maintenance: 2026-03-20'),
('mauvais', 'moyen', 'bon', 'mauvais', '2026-01-24', NULL, 6, 8, 'Etat: Critique\r\nActions: Réparer les fuites de plomberie et remplacer les tuyaux endommagés.\r\nVérifier et remplacer les éléments défectueux du système de chauffage.\r\nNettoyer et inspecter les circuits électriques pour prévenir les risques.\r\nDate de maintenance Recommendée: 2026-03-20'),
('bon', 'moyen', 'moyen', 'mauvais', '2023-05-22', NULL, 8, 10, 'Etat: Modéré\r\nActions: Vérifier et réparer le système de chauffage, inspecter la plomberie et l\'électricité pour prévenir les pannes, nettoyer les conduits de ventilation.\r\nDate de maintenance: 2026-03-20'),
('mauvais', 'mauvais', 'bon', 'bon', '2020-09-03', NULL, 9, 11, 'Etat: Critique\nActions: Réparer les fuites de plomberie et remplacer les tuyaux endommagés.\nActions: Inspecter et renforcer la structure générale du bâtiment.\nActions: Vérifier et nettoyer les systèmes de ventilation.\nDate de maintenance Recommendée: 2026-03-22'),
('bon', 'bon', 'bon', 'mauvais', '2023-12-08', NULL, 10, 12, 'Etat: Modéré\nActions: Vérifier et remplacer les éléments défectueux du système de chauffage.\nActions: Nettoyer les radiateurs et purger les circuits si nécessaire.\nActions: Inspecter les joints et les fuites potentielles dans le système.\nDate de maintenance Recommendée: 2026-03-23'),
('bon', 'bon', 'bon', 'moyen', '2024-03-10', NULL, 11, 13, 'Etat: Modéré\nActions: Vérifier et entretenir le système de chauffage pour éviter une détérioration.\nInspecter les joints et robinetterie pour prévenir les fuites.\nContrôler les installations électriques pour détecter d\'éventuels signes d\'usure.\nDate de maintenance Recommendée: 2026-03-22'),
('mauvais', 'moyen', 'bon', 'mauvais', '2022-07-04', NULL, 12, 14, 'Etat: Critique\r\nActions: Réparer les fuites de plomberie et remplacer les tuyaux corrodés.\r\nActions: Remplacer le système de chauffage défectueux et vérifier les radiateurs.\r\nActions: Inspecter et renforcer la structure générale du bâtiment.\r\nDate de maintenance Recommendée: 2026-04-01'),
('mauvais', 'bon', 'mauvais', 'bon', '2026-05-08', NULL, 13, 15, 'Etat: Critique\n\nActions:\nRemplacer le tableau électrique obsolète et non conforme aux normes.\nVérifier et remplacer les câbles défectueux dans les circuits critiques.\nContrôler les prises et interrupteurs pour détecter d\'éventuels dysfonctionnements ou risques d\'incendie.\n\nDate de maintenance Recommendée: 2026-06-05'),
('bon', 'mauvais', 'moyen', 'bon', '2025-03-09', NULL, 14, 16, 'NULL'),
('moyen', 'moyen', 'bon', 'bon', '2025-04-16', NULL, 15, 17, 'Etat: Modéré\r\nActions: Vérifier les fuites de plomberie et remplacer les joints usés. Inspecter les systèmes de ventilation et nettoyer les conduits si nécessaire.\r\nDate de maintenance: 2026-03-20'),
('bon', 'mauvais', 'bon', 'moyen', '2026-05-08', NULL, 17, 19, 'Etat: Critique\n\nActions: Remplacer les tuyaux et joints défectueux de la plomberie pour éviter fuites ou infiltrations (priorité absolue).\nVérifier et entretenir la chaudière ou les radiateurs (chauffage en état moyen, risque de panne hivernale).\nContrôler les tableaux électriques malgré leur bon état (dernière maintenance datée de 2022).\n\nDate de maintenance Recommendée: 2026-06-05'),
('bon', 'bon', 'moyen', 'bon', '2022-09-22', NULL, 18, 20, 'Etat: Modéré\r\nActions: Vérifier et mettre à jour le système électrique, inspecter les circuits et les prises. Contrôler l\'état des joints de plomberie.\r\nDate de maintenance: 2026-03-23'),
('mauvais', 'moyen', 'mauvais', 'moyen', '2025-05-16', NULL, 19, 21, 'Etat: Critique\r\nActions: Réparer les fuites de plomberie et remplacer les tuyaux corrodés.\r\nActions: Vérifier et remplacer les câbles électriques défectueux pour éviter les risques.\r\nActions: Inspecter et entretenir la chaudière et les radiateurs pour optimiser le chauffage.\r\nDate de maintenance Recommendée: 2026-04-01'),
('bon', 'bon', 'moyen', 'mauvais', '2026-05-08', NULL, 20, 22, 'Etat: Critique\n\nActions:\nRemplacer ou réparer le système de chauffage (chaudière, radiateurs, thermostats).\nVérifier et corriger les éventuelles fuites ou problèmes d\'isolation thermique.\nFaire un diagnostic complet du circuit de chauffage pour identifier les causes du mauvais état.\n\nDate de maintenance Recommendée: 2026-06-05'),
('moyen', 'moyen', 'moyen', 'mauvais', NULL, NULL, 21, 43, NULL),
('Unknown', 'Unknown', 'Unknown', 'Unknown', '2026-05-08', 'Automatic AI Initial Scan', 22, 44, 'Etat: Critique\n\nActions: Vérification complète urgente des installations (électricité, plomberie, chauffage) en raison de données manquantes et risque potentiel de défaillances non détectées.\nContrôle structurel et étanchéité (10 m² suggère espace réduit, risque accru d\'humidité ou surcharge).\nRemplacement préventif des éléments vétustes ou non conformes (priorité aux systèmes critiques non inspectés).\n\nDate de maintenance Recommendée: 2026-06-05'),
('Unknown', 'Unknown', 'Unknown', 'Unknown', '2026-05-08', 'Automatic AI Initial Scan', 25, 45, 'Etat: Unknown (Urgent à évaluer)\n\nActions: Réaliser un diagnostic complet (plomberie, électricité, chauffage) pour identifier les risques cachés et prioriser les réparations.\nVérifier les équipements essentiels (chaudière, robinetterie, tableau électrique) et remplacer les pièces usées ou non conformes.\nNettoyer les systèmes de ventilation et inspecter les signes d’humidité ou de moisissures dans les pièces humides.\n\nDate de maintenance Recommendée: 2026-06-05');
